/* ========================================
   WellStream Platform — Design System
   ======================================== */

/* --- CSS Variables --- */
:root {
  /* Core palette */
  --bg-deep: #0D1B2A;
  --bg-base: #111827;
  --bg-elevated: #1B2838;
  --bg-surface: #1F2D3F;
  --bg-card: #1A2940;

  /* Brand */
  --navy: #15295A;
  --green: #6CC24A;
  --gray-dark: #3C424B;

  /* Accent */
  --teal: #00B4D8;
  --teal-hover: #0096B4;
  --blue: #0077B6;
  --blue-hover: #006099;

  /* Text */
  --text-primary: #FFFFFF;
  --text-secondary: #CBD5E1;
  --text-muted: #94A3B8;
  --text-dim: #64748B;

  /* Surfaces */
  --border-subtle: rgba(255,255,255,0.08);
  --border-default: rgba(255,255,255,0.12);
  --border-active: rgba(0,180,216,0.3);

  /* Feedback */
  --error: #EF4444;
  --success: #6CC24A;

  /* Typography */
  --font-heading: 'Poppins', 'Inter', sans-serif;
  --font-body: 'Open Sans', 'Inter', sans-serif;

  /* Spacing scale (4pt) */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;
  --space-20: 80px;
  --space-24: 96px;

  /* Layout */
  --max-width: 1280px;
  --radius-sm: 6px;
  --radius: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  /* Animation */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in: cubic-bezier(0.4, 0, 1, 1);
  --duration-fast: 150ms;
  --duration-base: 200ms;
  --duration-slow: 300ms;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.3);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.4);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.5);
  --shadow-glow: 0 0 20px rgba(0,180,216,0.15);
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-secondary);
  background: var(--bg-deep);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}
img { max-width: 100%; height: auto; display: block; }
a { color: var(--teal); text-decoration: none; transition: color var(--duration-fast) var(--ease-out); }
a:hover { color: var(--teal-hover); }
ul { list-style: none; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--text-primary);
  line-height: 1.2;
  font-weight: 600;
}
h1 { font-size: clamp(2rem, 4vw, 3.25rem); }
h2 { font-size: clamp(1.5rem, 3vw, 2.25rem); }
h3 { font-size: clamp(1.15rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

.section-label {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--teal);
  margin-bottom: var(--space-3);
}
.section-heading {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 700;
  margin-bottom: var(--space-4);
  color: var(--text-primary);
}
.section-subtitle {
  font-size: 1.05rem;
  color: var(--text-muted);
  max-width: 640px;
  line-height: 1.7;
}

/* --- Container --- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}
@media (min-width: 1024px) {
  .container { padding: 0 var(--space-10); }
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: 12px 24px;
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: var(--radius);
  cursor: pointer;
  transition: all var(--duration-fast) var(--ease-out);
  border: 2px solid transparent;
  white-space: nowrap;
  text-decoration: none;
  min-height: 44px;
  min-width: 44px;
  line-height: 1;
}
.btn:hover { text-decoration: none; }
.btn:focus-visible { outline: 2px solid var(--teal); outline-offset: 2px; }

.btn-primary {
  background: var(--teal);
  color: var(--bg-deep);
  border-color: var(--teal);
}
.btn-primary:hover {
  background: var(--teal-hover);
  border-color: var(--teal-hover);
  color: var(--bg-deep);
  box-shadow: var(--shadow-glow);
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border-color: var(--border-default);
}
.btn-secondary:hover {
  background: rgba(255,255,255,0.06);
  border-color: var(--border-active);
  color: var(--text-primary);
}

.btn-outline-teal {
  background: transparent;
  color: var(--teal);
  border-color: var(--teal);
}
.btn-outline-teal:hover {
  background: rgba(0,180,216,0.1);
  color: var(--teal-hover);
}

.btn-green {
  background: var(--green);
  color: #000;
  border-color: var(--green);
}
.btn-green:hover { background: #5AA83A; border-color: #5AA83A; color: #000; }

/* --- Navigation --- */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(13, 27, 42, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-subtle);
  padding: 0 var(--space-6);
}
.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: var(--space-2);
}
.nav-logo:hover { color: var(--teal); }
.nav-logo .logo-icon {
  width: 32px; height: 32px;
  background: var(--teal);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bg-deep);
  font-weight: 800;
  font-size: 1rem;
}
.nav-links { display: flex; align-items: center; gap: var(--space-1); }
.nav-links a {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  transition: all var(--duration-fast) var(--ease-out);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.nav-links a:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); }

/* Dropdown */
.dropdown { position: relative; }
.dropdown-toggle { cursor: pointer; }
.dropdown-toggle::after {
  content: '';
  display: inline-block;
  width: 6px; height: 6px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: rotate(45deg);
  margin-left: 2px;
  margin-top: -2px;
  transition: transform var(--duration-fast) var(--ease-out);
}
.dropdown.open .dropdown-toggle::after { transform: rotate(-135deg); margin-top: 2px; }
.dropdown-menu {
  position: absolute;
  top: 100%;
  left: 0;
  margin-top: 4px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: var(--space-2);
  min-width: 200px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--duration-fast) var(--ease-out);
  box-shadow: var(--shadow-lg);
}
.dropdown.open .dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
.dropdown-menu a {
  display: flex;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.825rem;
  color: var(--text-secondary) !important;
}
.dropdown-menu a:hover { background: rgba(0,180,216,0.08); color: var(--teal) !important; }

/* Hamburger */
.nav-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  padding: 8px;
  min-width: 44px;
  min-height: 44px;
}
.nav-toggle span {
  display: block;
  width: 24px; height: 2px;
  background: var(--text-primary);
  margin: 5px 0;
  transition: all var(--duration-base) var(--ease-out);
}
.nav-toggle.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.nav-toggle.active span:nth-child(2) { opacity: 0; }
.nav-toggle.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* --- Mobile Nav --- */
@media (max-width: 1023px) {
  .nav-toggle { display: block; }
  .nav-links {
    display: none;
    position: absolute;
    top: 64px;
    left: 0;
    right: 0;
    background: var(--bg-elevated);
    border-bottom: 1px solid var(--border-default);
    flex-direction: column;
    padding: var(--space-4);
    gap: var(--space-1);
    box-shadow: var(--shadow-lg);
  }
  .nav-links.open { display: flex; }
  .nav-links .dropdown-menu {
    position: static;
    box-shadow: none;
    border: none;
    background: rgba(0,0,0,0.2);
    padding-left: var(--space-4);
    display: none;
  }
  .dropdown.open .dropdown-menu { display: block; }
  .nav-links a { width: 100%; }
}

/* --- Hero --- */
.hero {
  position: relative;
  padding: var(--space-20) 0 var(--space-16);
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 60% 60% at 50% 0%, rgba(0,180,216,0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
  text-align: center;
  position: relative;
  z-index: 1;
}
.hero h1 {
  font-size: clamp(2rem, 4.5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: var(--space-6);
  letter-spacing: -0.02em;
}
.hero h1 .highlight { color: var(--teal); }
.hero p {
  font-size: clamp(1rem, 1.5vw, 1.15rem);
  color: var(--text-muted);
  max-width: 620px;
  margin: 0 auto var(--space-8);
  line-height: 1.7;
}
.hero-actions {
  display: flex;
  gap: var(--space-3);
  justify-content: center;
  flex-wrap: wrap;
}

/* Page hero (smaller) */
.page-hero {
  padding: var(--space-16) 0 var(--space-12);
  text-align: center;
  background: radial-gradient(ellipse 50% 50% at 50% 0%, rgba(0,180,216,0.06) 0%, transparent 70%);
}
.page-hero h1 { margin-bottom: var(--space-4); }
.page-hero p { max-width: 600px; margin: 0 auto; color: var(--text-muted); }

/* --- Sections --- */
.section {
  padding: var(--space-20) 0;
}
.section-dark {
  background: var(--bg-base);
}
.section-header {
  text-align: center;
  margin-bottom: var(--space-12);
}

/* --- Cards --- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--duration-base) var(--ease-out);
}
.card:hover {
  border-color: var(--border-active);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

/* --- Grid --- */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-6); }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6); }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-6); }

@media (max-width: 1023px) {
  .grid-3, .grid-4 { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 767px) {
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
}

/* --- Tabs --- */
.tabs-nav {
  display: flex;
  gap: var(--space-1);
  border-bottom: 1px solid var(--border-default);
  margin-bottom: var(--space-8);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}
.tab-btn {
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-muted);
  background: none;
  border: none;
  padding: 12px 20px;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all var(--duration-fast) var(--ease-out);
  white-space: nowrap;
  min-height: 44px;
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active {
  color: var(--teal);
  border-bottom-color: var(--teal);
}
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* --- Accordion --- */
.accordion-item {
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  margin-bottom: var(--space-3);
  overflow: hidden;
  transition: border-color var(--duration-fast) var(--ease-out);
}
.accordion-item:hover { border-color: var(--border-default); }
.accordion-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-5) var(--space-6);
  background: var(--bg-card);
  border: none;
  color: var(--text-primary);
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 600;
  cursor: pointer;
  text-align: left;
  transition: background var(--duration-fast) var(--ease-out);
  min-height: 56px;
}
.accordion-header:hover { background: var(--bg-elevated); }
.accordion-header:focus-visible { outline: 2px solid var(--teal); outline-offset: -2px; }
.accordion-icon {
  flex-shrink: 0;
  width: 28px; height: 28px;
  border-radius: 50%;
  background: rgba(0,180,216,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--duration-base) var(--ease-out);
  color: var(--teal);
}
.accordion-item.open .accordion-icon { transform: rotate(45deg); }
.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--duration-slow) var(--ease-out);
}
.accordion-body-inner {
  padding: 0 var(--space-6) var(--space-6);
  color: var(--text-muted);
  line-height: 1.7;
}

/* --- Stats Circles --- */
.stats-row {
  display: flex;
  justify-content: center;
  gap: var(--space-12);
  flex-wrap: wrap;
}
.stat-circle {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: var(--space-3);
}
.stat-circle .circle {
  width: 140px;
  height: 140px;
  border-radius: 50%;
  border: 3px solid var(--teal);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: rgba(0,180,216,0.04);
  transition: all var(--duration-base) var(--ease-out);
}
.stat-circle .circle:hover {
  box-shadow: var(--shadow-glow);
  background: rgba(0,180,216,0.08);
}
.stat-circle .circle .number {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 700;
  color: var(--teal);
  line-height: 1;
}
.stat-circle .circle .unit {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 2px;
}
.stat-circle .label {
  font-size: 0.875rem;
  color: var(--text-secondary);
  max-width: 160px;
  line-height: 1.4;
}

/* --- Timeline --- */
.timeline { max-width: 720px; margin: 0 auto; }
.timeline-item {
  margin-bottom: var(--space-8);
  position: relative;
}
.timeline-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: var(--space-3);
}
.timeline-period {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--teal);
}
.timeline-desc {
  font-size: 0.9rem;
  color: var(--text-muted);
}
.timeline-bar {
  height: 8px;
  background: rgba(255,255,255,0.06);
  border-radius: 4px;
  overflow: hidden;
  position: relative;
}
.timeline-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--teal), var(--blue));
  border-radius: 4px;
  transition: width 1s var(--ease-out);
}

/* --- Testimonial Carousel --- */
.carousel {
  position: relative;
  max-width: 720px;
  margin: 0 auto;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  transition: transform var(--duration-slow) var(--ease-out);
}
.carousel-slide {
  min-width: 100%;
  padding: var(--space-6);
}
.carousel-slide blockquote {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  position: relative;
}
.carousel-slide blockquote::before {
  content: '\201C';
  font-family: var(--font-heading);
  font-size: 4rem;
  color: var(--teal);
  opacity: 0.3;
  position: absolute;
  top: 8px;
  left: 16px;
  line-height: 1;
}
.carousel-slide blockquote p {
  font-size: 1.05rem;
  color: var(--text-secondary);
  font-style: italic;
  line-height: 1.7;
  margin-bottom: var(--space-4);
}
.carousel-slide blockquote footer {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
}
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: var(--space-2);
  margin-top: var(--space-6);
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-default);
  border: none;
  cursor: pointer;
  padding: 0;
  min-width: 44px;
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--duration-fast) var(--ease-out);
}
.carousel-dot::after {
  content: '';
  width: 10px; height: 10px;
  border-radius: 50%;
  background: inherit;
  transition: background var(--duration-fast) var(--ease-out);
}
.carousel-dot.active::after { background: var(--teal); }

/* --- Platform Diagram --- */
.platform-diagram {
  display: flex;
  justify-content: center;
  gap: var(--space-8);
  flex-wrap: wrap;
  margin-top: var(--space-8);
}
.platform-pillar {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  text-align: center;
  flex: 1;
  min-width: 280px;
  max-width: 360px;
  transition: all var(--duration-base) var(--ease-out);
}
.platform-pillar:hover {
  border-color: var(--border-active);
  box-shadow: var(--shadow-md);
}
.platform-pillar .pillar-icon {
  width: 56px; height: 56px;
  border-radius: var(--radius-lg);
  background: rgba(0,180,216,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-5);
  color: var(--teal);
}
.platform-pillar h3 {
  font-size: 1.1rem;
  margin-bottom: var(--space-2);
}
.platform-pillar p {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* --- Data Lifecycle Diagram --- */
.lifecycle-flow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  flex-wrap: wrap;
  margin-top: var(--space-8);
}
.lifecycle-step {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--space-5) var(--space-6);
  text-align: center;
  min-width: 160px;
  position: relative;
  transition: all var(--duration-base) var(--ease-out);
}
.lifecycle-step:hover {
  border-color: var(--border-active);
  box-shadow: var(--shadow-md);
}
.lifecycle-step .step-num {
  font-family: var(--font-heading);
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--teal);
  letter-spacing: 0.05em;
  margin-bottom: var(--space-1);
}
.lifecycle-step h4 {
  font-size: 0.95rem;
  margin-bottom: var(--space-1);
}
.lifecycle-step p {
  font-size: 0.8rem;
  color: var(--text-muted);
}
.lifecycle-arrow {
  color: var(--teal);
  font-size: 1.5rem;
  font-weight: 300;
  flex-shrink: 0;
}
@media (max-width: 767px) {
  .lifecycle-arrow { transform: rotate(90deg); }
}

/* --- Form --- */
