}
.dropdown.open .dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }
.dropdown-menu a {
  display: flex;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.825rem;
  color: var(--text-secondary) !important;
}
.dropdown-menu a:hover { background: rgba(0,180,216,0.08); color: var(--teal) !important; }

/* Hamburger */
.nav-toggle {
  display: none;
  background: none;
  border: none;
