@media (max-width: 767px) {
  .security-features { grid-template-columns: 1fr; }
}

/* --- ETL Benefits --- */
.etl-benefits {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
}
.etl-benefit {
  display: flex;
  gap: var(--space-4);
  align-items: flex-start;
}
.etl-benefit .check-circle {
