<script>
// Navigation
(function(){
  var navToggle = document.getElementById('navToggle');
  var navLinks = document.getElementById('navLinks');
  var platformDropdown = document.getElementById('platformDropdown');
  var platformToggle = document.getElementById('platformDropdownToggle');

  navToggle.addEventListener('click', function(){
    this.classList.toggle('active');
    navLinks.classList.toggle('open');
    this.setAttribute('aria-expanded', this.classList.contains('active'));
  });

  platformToggle.addEventListener('click', function(e){
    e.preventDefault();
    e.stopPropagation();
    platformDropdown.classList.toggle('open');
    platformToggle.setAttribute('aria-expanded', platformDropdown.classList.contains('open'));
  });

  document.addEventListener('click', function(e){
    if (!platformDropdown.contains(e.target)) {
      platformDropdown.classList.remove('open');
      platformToggle.setAttribute('aria-expanded', 'false');
    }
  });

  navLinks.querySelectorAll('a').forEach(function(link){
    link.addEventListener('click', function(){
      navLinks.classList.remove('open');
      navToggle.classList.remove('active');
      navToggle.setAttribute('aria-expanded', 'false');
    });
  });
})();

// Form Validation
(function(){
  var form = document.getElementById('demoForm');
  var success = document.getElementById('formSuccess');

  function showError(fieldId){
    var field = document.getElementById(fieldId);
    var error = document.getElementById(fieldId + 'Error');
    if (field) field.classList.add('error');
    if (error) error.classList.add('visible');
  }

  function clearError(fieldId){
    var field = document.getElementById(fieldId);
    var error = document.getElementById(fieldId + 'Error');
    if (field) field.classList.remove('error');
    if (error) error.classList.remove('visible');
  }

  function validateEmail(email){
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  }

  // Blur validation
  var fields = ['firstName', 'lastName', 'email', 'company', 'country'];
  fields.forEach(function(id){
    var field = document.getElementById(id);
    if (!field) return;
    field.addEventListener('blur', function(){
      var val = this.value.trim();
      if (!val) { showError(id); }
      else if (id === 'email' && !validateEmail(val)) { showError(id); }
      else { clearError(id); }
    });
    field.addEventListener('input', function(){
      if (this.classList.contains('error')) clearError(id);
    });
  });

  // Country change
  var country = document.getElementById('country');
  if (country) {
    country.addEventListener('change', function(){
      if (this.value) clearError('country');
    });
  }

  // Submit
  form.addEventListener('submit', function(e){
    e.preventDefault();
    var valid = true;
    var firstError = null;

    // Validate required fields
    var requiredFields = [
      { id: 'firstName', val: document.getElementById('firstName').value.trim() },
      { id: 'lastName', val: document.getElementById('lastName').value.trim() },
      { id: 'email', val: document.getElementById('email').value.trim() },
      { id: 'company', val: document.getElementById('company').value.trim() },
      { id: 'country', val: document.getElementById('country').value.trim() }
    ];

    requiredFields.forEach(function(f){
      if (!f.val) {
        showError(f.id);
        valid = false;
        if (!firstError) firstError = f.id;
      } else if (f.id === 'email' && !validateEmail(f.val)) {
        showError(f.id);
        valid = false;
        if (!firstError) firstError = f.id;
      }
    });

    if (!valid) {
      if (firstError) document.getElementById(firstError).focus();
      return;
    }

    // Success
    form.style.display = 'none';
    success.classList.add('visible');
    success.scrollIntoView({ behavior: 'smooth', block: 'center' });
  });
})();
</script>

